+import { verifySessionToken, SignedSessionToken } from "./session-signer.ts";
+import { getRevokedSessionsSnapshot } from "./session-revocation.ts";
+
+export interface EdgeValidationSnapshot {
+  timestamp: number;
+  revoked: Record<string, number>;
+}
+
+export const getEdgeValidationSnapshot = (): EdgeValidationSnapshot => {
+  const snapshot = getRevokedSessionsSnapshot();
+  const revoked: Record<string, number> = {};
+
+  for (const entry of snapshot) {
+    revoked[entry.sessionId] = entry.revokedAt;
+  }
+
+  return {
+    timestamp: Math.floor(Date.now() / 1000),
+    revoked,
+  };
+};
+
+export const validateSessionTokenOnEdge = (
+  token: string,
+  revokedSessions: Record<string, number>,
+): SignedSessionToken | null => {
+  const verified = verifySessionToken(token);
+  if (!verified) return null;
+
+  const revokedAt = revokedSessions[verified.sessionId];
+  if (revokedAt !== undefined && revokedAt > verified.issuedAt) {
+    return null;
+  }
+
+  return verified;
+};
