@@ -0,0 +1,46 @@
+import { pool } from "./pool.ts";
+
+interface RevokedSession {
+  sessionId: string;
+  revokedAt: number;
+}
+
+let revokedSessions: Map<string, number> = new Map();
+
+export const initRevocationCache = async (): Promise<void> => {
+  await reloadRevokedSessions();
+  setInterval(reloadRevokedSessions, 5000);
+};
+
+const reloadRevokedSessions = async (): Promise<void> => {
+  try {
+    const result = await pool.query(
+      "SELECT id, EXTRACT(EPOCH FROM revoked_at)::bigint as revoked_at FROM sessions WHERE revoked_at IS NOT NULL",
+    );
+
+    const newCache: Map<string, number> = new Map();
+    for (const row of result.rows) {
+      newCache.set(row.id, row.revoked_at);
+    }
+    revokedSessions = newCache;
+  } catch (error) {
+    console.error("Failed to reload revoked sessions:", error);
+  }
+};
+
+export const isSessionRevoked = (
+  sessionId: string,
+  issuedAt: number,
+): boolean => {
+  const revokedAt = revokedSessions.get(sessionId);
+  if (revokedAt === undefined) return false;
+  return revokedAt > issuedAt;
+};
+
+export const getRevokedSessionsSnapshot = (): RevokedSession[] => {
+  const snapshot: RevokedSession[] = [];
+  revokedSessions.forEach((revokedAt, sessionId) => {
+    snapshot.push({ sessionId, revokedAt });
+  });
+  return snapshot;
+};
