@@ -0,0 +1,55 @@
+import { createHmac } from "crypto";
+
+const SESSION_SECRET = process.env.SESSION_SECRET || "dev-secret-change-in-prod";
+
+export interface SignedSessionToken {
+  sessionId: string;
+  userId: string;
+  issuedAt: number;
+  signature: string;
+}
+
+export const signSession = (
+  sessionId: string,
+  userId: string,
+): string => {
+  const issuedAt = Math.floor(Date.now() / 1000);
+  const payload = JSON.stringify({ sessionId, userId, issuedAt });
+  const payloadB64 = Buffer.from(payload).toString("base64");
+
+  const signature = createHmac("sha256", SESSION_SECRET)
+    .update(payloadB64)
+    .digest("base64");
+
+  return `${payloadB64}.${signature}`;
+};
+
+export const verifySessionToken = (
+  token: string,
+): SignedSessionToken | null => {
+  try {
+    const [payloadB64, signature] = token.split(".");
+    if (!payloadB64 || !signature) return null;
+
+    const expectedSignature = createHmac("sha256", SESSION_SECRET)
+      .update(payloadB64)
+      .digest("base64");
+
+    if (signature !== expectedSignature) {
+      return null;
+    }
+
+    const payload = JSON.parse(
+      Buffer.from(payloadB64, "base64").toString(),
+    );
+
+    return {
+      sessionId: payload.sessionId,
+      userId: payload.userId,
+      issuedAt: payload.issuedAt,
+      signature,
+    };
+  } catch {
+    return null;
+  }
+};
